import {
  collection,
  deleteDoc,
  doc,
  getDoc,
  getDocs,
  orderBy,
  query,
  serverTimestamp,
  setDoc,
  updateDoc,
  where,
} from "firebase/firestore";
import type { UserProfile, UserRole, UserStatus } from "../../features/admin/types";

export type CreateUserInput = {
  uid: string;
  fullName: string;
  email: string;
  phoneNumber?: string;
  role: UserRole;
  language?: string;
  createdBy: string;
};

export type UpdateUserInput = Partial<
  Pick<UserProfile, "fullName" | "phoneNumber" | "role" | "status" | "language" | "photoURL">
> & { updatedBy: string };

async function getDb() {
  const { db } = await import("../../lib/firebase");
  return db;
}

export async function createUser(input: CreateUserInput): Promise<void> {
  const db = await getDb();
  const ref = doc(db, "users", input.uid);
  await setDoc(ref, {
    uid: input.uid,
    fullName: input.fullName,
    email: input.email,
    phoneNumber: input.phoneNumber ?? null,
    role: input.role,
    status: "active" as UserStatus,
    language: input.language ?? null,
    photoURL: null,
    createdAt: serverTimestamp(),
    updatedAt: serverTimestamp(),
    createdBy: input.createdBy,
    updatedBy: null,
  });
}

export async function updateUser(uid: string, input: UpdateUserInput): Promise<void> {
  const db = await getDb();
  const ref = doc(db, "users", uid);
  await updateDoc(ref, {
    ...input,
    updatedAt: serverTimestamp(),
  });
}

export async function getUserById(uid: string): Promise<UserProfile | null> {
  const db = await getDb();
  const ref = doc(db, "users", uid);
  const snap = await getDoc(ref);
  if (!snap.exists()) return null;
  return snap.data() as UserProfile;
}

export async function listUsers(): Promise<UserProfile[]> {
  const db = await getDb();
  const q = query(collection(db, "users"), orderBy("createdAt", "desc"));
  const snap = await getDocs(q);
  return snap.docs.map((d) => d.data() as UserProfile);
}

export async function listUsersByRole(role: UserRole): Promise<UserProfile[]> {
  const db = await getDb();
  const q = query(
    collection(db, "users"),
    where("role", "==", role),
    orderBy("createdAt", "desc")
  );
  const snap = await getDocs(q);
  return snap.docs.map((d) => d.data() as UserProfile);
}

export async function setUserStatus(uid: string, status: UserStatus, updatedBy: string): Promise<void> {
  await updateUser(uid, { status, updatedBy });
}

export async function deleteUser(uid: string): Promise<void> {
  const db = await getDb();
  await deleteDoc(doc(db, "users", uid));
}
